fn read_records(reader: Box<dyn Read>, delimiter: u8) -> Result<Vec<Vec<String>>, csv::Error> {
    let mut csv = csv::ReaderBuilder::new()
        .has_headers(false)
        .delimiter(delimiter)
        .from_reader(reader);

