                top_mid: '┬',
                top_right: '┐',
                mid_left: '├',
                mid_mid: '┼',
                mid_right: '┤',
                bottom_left: '└',
                bottom_mid: '┴',
                bottom_right: '┘',
                horizontal: '─',
                vertical: '│',
                body_separators: false,
            },
        ),
        Style::Rounded => render_box(
            cli,
