#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum Style {
    None,
    Ascii,
    #[value(name = "ascii2")]
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq, ValueEnum)]
enum Align {
    Left,
    Center,
    Right,
}

#[derive(Debug, Parser)]
#[command(
    name = "csview",
    bin_name = "executable",
    version = "1.3.4",
    about = "A high performance csv viewer with cjk/emoji support."
)]
struct Cli {
    #[arg(short = 'H', long = "no-headers", help = "Specify that the input has no header row")]
    no_headers: bool,

    #[arg(short = 'n', long = "number", help = "Prepend a column of line numbers to the table")]
    number: bool,

    #[arg(short = 't', long = "tsv", conflicts_with = "delimiter", help = "Use '\\t' as delimiter for tsv")]
    tsv: bool,

    #[arg(
        short = 'd',
        long = "delimiter",
        default_value_t = ',',
        value_name = "DELIMITER",
        help = "Specify the field delimiter"
    )]
    delimiter: char,

    #[arg(
        short = 's',
        long = "style",
        default_value_t = Style::Sharp,
        value_name = "STYLE",
        help = "Specify the border style"
    )]
    style: Style,

    #[arg(
        short = 'p',
        long = "padding",
        default_value_t = 1,
        value_name = "PADDING",
        help = "Specify padding for table cell"
    )]
    padding: usize,

    #[arg(
        short = 'i',
        long = "indent",
        default_value_t = 0,
        value_name = "INDENT",
        help = "Specify global indent for table"
    )]
    indent: usize,

    #[arg(
        long = "sniff",
        default_value_t = 1000,
        value_name = "LIMIT",
        help = "Limit column widths sniffing to the specified number of rows. Specify \"0\" to cancel limit"
    )]
    sniff: usize,

    #[arg(
        long = "header-align",
        default_value_t = Align::Center,
        value_name = "HEADER_ALIGN",
        help = "Specify the alignment of the table header"
    )]
    header_align: Align,

    #[arg(
        long = "body-align",
        default_value_t = Align::Left,
        value_name = "BODY_ALIGN",
        help = "Specify the alignment of the table body"
    )]
    body_align: Align,

    #[arg(short = 'P', long = "disable-pager", help = "Disable pager")]
    disable_pager: bool,

    #[arg(value_name = "FILE", help = "File to view")]
    file: Option<PathBuf>,
}

#[derive(Clone, Copy)]
struct BoxStyle {
    top_left: char,
    top_mid: char,
    top_right: char,
    mid_left: char,
    mid_mid: char,
    mid_right: char,
    bottom_left: char,
    bottom_mid: char,
    bottom_right: char,
    horizontal: char,
    vertical: char,
    body_separators: bool,
}

fn main() -> ExitCode {
    let cli = Cli::parse();

    let input = match open_input(cli.file.as_deref()) {
        Ok(input) => input,
        Err(error) => {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    };

    let delimiter = if cli.tsv {
        b'\t'
    } else {
        cli.delimiter as u32 as u8
    };

    let records = match read_records(input, delimiter) {
        Ok(records) => records,
        Err(error) => {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    };

    let table = build_table(&cli, records);
    let rendered = render_table(&cli, &table);

    let mut stdout = io::stdout().lock();
    if let Err(error) = stdout.write_all(rendered.as_bytes()) {
        if error.kind() != io::ErrorKind::BrokenPipe {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    }

    ExitCode::SUCCESS
}

