fn render_border(
    widths: &[usize],
    padding: usize,
    left: char,
    mid: char,
    right: char,
    horizontal: char,
) -> String {
    if widths.is_empty() {
        return format!("{left}{right}");
    }

    let segments = widths
        .iter()
        .map(|width| horizontal.to_string().repeat(width + (padding * 2)))
        .collect::<Vec<_>>();
    format!("{left}{}{right}", segments.join(&mid.to_string()))
}

fn render_box_row(
    row: &[String],
    widths: &[usize],
    padding: usize,
    align: Align,
    vertical: char,
) -> String {
    if widths.is_empty() {
        return format!("{vertical}{vertical}");
    }

    let cells = widths
        .iter()
        .zip(row.iter())
        .map(|(width, cell)| render_cell(cell, *width, padding, align))
        .collect::<Vec<_>>();
    format!("{vertical}{}{vertical}", cells.join(&vertical.to_string()))
}

fn render_flat_row(
    row: &[String],
    widths: &[usize],
    padding: usize,
    align: Align,
    left_edge: &str,
    separator: &str,
    right_edge: &str,
) -> String {
    if widths.is_empty() {
        return format!("{left_edge}{right_edge}");
    }

    let cells = widths
        .iter()
        .zip(row.iter())
        .map(|(width, cell)| render_cell(cell, *width, padding, align))
        .collect::<Vec<_>>();
    format!("{left_edge}{}{right_edge}", cells.join(separator))
}

fn render_separator_row(
    widths: &[usize],
    padding: usize,
    left_edge: &str,
    separator: &str,
    right_edge: &str,
    fill: char,
    outer_padding: Option<char>,
) -> String {
    if widths.is_empty() {
        return match outer_padding {
            Some(ch) => format!("{ch}{left_edge}{right_edge}{ch}"),
            None => format!("{left_edge}{right_edge}"),
        };
    }

    let cells = widths
        .iter()
        .map(|width| fill.to_string().repeat(width + (padding * 2)))
        .collect::<Vec<_>>();
    let mut line = format!("{left_edge}{}{right_edge}", cells.join(separator));

    if let Some(ch) = outer_padding {
        line.insert(0, ch);
        line.push(ch);
    }

    line
}

fn render_cell(text: &str, width: usize, padding: usize, align: Align) -> String {
    let text = truncate_to_width(text, width);
    let text_width = display_width(&text);
    let slack = width.saturating_sub(text_width);
    let (left_extra, right_extra) = match align {
        Align::Left => (0, slack),
        Align::Center => (slack / 2, slack - (slack / 2)),
        Align::Right => (slack, 0),
    };

    format!(
        "{}{}{}",
        " ".repeat(padding + left_extra),
        text,
        " ".repeat(padding + right_extra)
    )
}

fn truncate_to_width(text: &str, max_width: usize) -> String {
    if display_width(text) <= max_width {
        return text.to_owned();
    }

    let mut result = String::new();
    let mut width = 0;

    // Later rows are clipped to the sniffed width with no ellipsis.
    for grapheme in UnicodeSegmentation::graphemes(text, true) {
        let grapheme_width = grapheme_width(grapheme);
        if width + grapheme_width > max_width {
            break;
        }
        result.push_str(grapheme);
        width += grapheme_width;
    }

    result
}

fn display_width(text: &str) -> usize {
    UnicodeSegmentation::graphemes(text, true)
        .map(grapheme_width)
        .sum()
}

fn grapheme_width(grapheme: &str) -> usize {
    let width = UnicodeWidthStr::width(grapheme);
    if width == 0 && grapheme.chars().any(char::is_control) {
        grapheme.chars().count()
    } else {
        width
    }
}

fn join_lines(lines: Vec<String>, indent: usize) -> String {
    let prefix = " ".repeat(indent);
    let mut output = String::new();

    for line in lines {
        output.push_str(&prefix);
        output.push_str(&line);
        output.push('\n');
    }

    output
}

