+
+            if byte == b'\n' {
+                record_fields.push(std::mem::take(&mut field));
+                just_closed_quote = false;
+                finalize_record(
+                    &mut records,
+                    &mut expected_fields,
+                    &mut record_fields,
+                    record_has_content,
+                    record_start_line,
+                    record_start_byte,
+                )?;
+                record_has_content = false;
+                line += 1;
+                index += 1;
+                record_start_line = line;
+                record_start_byte = index;
+                continue;
+            }
