+        if byte == delimiter {
+            record_fields.push(std::mem::take(&mut field));
+            record_has_content = true;
+            index += 1;
+            continue;
+        }
+
+        if byte == b'"' {
+            if field.is_empty() {
+                in_quotes = true;
+                record_has_content = true;
+                index += 1;
+                continue;
+            }
+
+            return Err(invalid_csv_syntax(records.len(), record_start_line, record_start_byte));
+        }
+
+        if byte == b'\n' {
+            record_fields.push(std::mem::take(&mut field));
+            finalize_record(
+                &mut records,
+                &mut expected_fields,
+                &mut record_fields,
+                record_has_content,
+                record_start_line,
+                record_start_byte,
