+        if byte == b'\r' {
+            record_fields.push(std::mem::take(&mut field));
+            finalize_record(
+                &mut records,
+                &mut expected_fields,
+                &mut record_fields,
+                record_has_content,
+                record_start_line,
+                record_start_byte,
+            )?;
+            record_has_content = false;
+            line += 1;
+            if data.get(index + 1) == Some(&b'\n') {
+                index += 2;
+            } else {
+                index += 1;
+            }
+            record_start_line = line;
+            record_start_byte = index;
+            continue;
