+
+fn finalize_record(
+    records: &mut Vec<Vec<String>>,
+    expected_fields: &mut Option<usize>,
+    record_fields: &mut Vec<Vec<u8>>,
+    record_has_content: bool,
+    record_start_line: usize,
+    record_start_byte: usize,
+) -> Result<(), String> {
+    if !record_has_content && record_fields.len() == 1 && record_fields[0].is_empty() {
+        record_fields.clear();
+        return Ok(());
+    }
+
+    let record_index = records.len();
+    let mut record = Vec::with_capacity(record_fields.len());
+    for field in record_fields.drain(..) {
+        let text = String::from_utf8(field)
+            .map_err(|_| invalid_csv_syntax(record_index, record_start_line, record_start_byte))?;
+        record.push(text);
+    }
+
+    if let Some(previous_fields) = expected_fields {
+        if record.len() != *previous_fields {
+            return Err(format!(
+                "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
+                record_index,
+                record_start_line,
+                record_start_byte,
+                record.len(),
+                previous_fields
+            ));
+        }
+    } else {
+        *expected_fields = Some(record.len());
+    }
+
+    records.push(record);
+    Ok(())
+}
+
+fn invalid_csv_syntax(record_index: usize, line: usize, byte: usize) -> String {
+    format!(
+        "CSV error: record {} (line: {}, byte: {}): found invalid CSV syntax",
+        record_index, line, byte
+    )
