+fn render_border(
+    widths: &[usize],
+    padding: usize,
+    left: char,
+    mid: char,
+    right: char,
+    horizontal: char,
+) -> String {
+    if widths.is_empty() {
+        return format!("{left}{right}");
+    }
+
+    let segments = widths
+        .iter()
+        .map(|width| repeat_char(horizontal, width + (padding * 2)))
+        .collect::<Vec<_>>();
