+    if widths.is_empty() {
+        return format!("{left_edge}{right_edge}");
+    }
+
+    let cells = widths
+        .iter()
+        .zip(row.iter())
+        .map(|(width, cell)| render_cell(cell, *width, padding, align))
+        .collect::<Vec<_>>();
+
+    format!("{left_edge}{}{right_edge}", cells.join(separator))
+}
+
+fn render_separator_row(
+    widths: &[usize],
+    padding: usize,
+    left_edge: &str,
+    separator: &str,
+    right_edge: &str,
+    fill: char,
+    outer_padding: Option<char>,
+) -> String {
+    if widths.is_empty() {
+        return match outer_padding {
+            Some(ch) => {
+                let mut line = String::new();
+                line.push(ch);
+                line.push_str(left_edge);
+                line.push_str(right_edge);
+                line.push(ch);
+                line
+            }
+            None => format!("{left_edge}{right_edge}"),
+        };
+    }
+
+    let cells = widths
+        .iter()
+        .map(|width| repeat_char(fill, width + (padding * 2)))
+        .collect::<Vec<_>>();
+
+    let mut line = format!("{left_edge}{}{right_edge}", cells.join(separator));
+    if let Some(ch) = outer_padding {
+        line.insert(0, ch);
+        line.push(ch);
+    }
+
+    line
+}
+
+fn render_cell(text: &str, width: usize, padding: usize, align: Align) -> String {
+    let text = truncate_to_width(text, width);
+    let text_width = display_width(&text);
+    let slack = width.saturating_sub(text_width);
+    let (left_extra, right_extra) = match align {
+        Align::Left => (0, slack),
+        Align::Center => (slack / 2, slack - (slack / 2)),
+        Align::Right => (slack, 0),
+    };
+
+    format!(
+        "{}{}{}",
+        " ".repeat(padding + left_extra),
+        text,
+        " ".repeat(padding + right_extra)
+    )
+}
+
+fn truncate_to_width(text: &str, max_width: usize) -> String {
+    if display_width(text) <= max_width {
+        return text.to_owned();
+    }
+
+    let mut output = String::new();
+    let mut width = 0;
+
+    // Later rows are clipped to the sniffed width with no ellipsis.
+    for ch in text.chars() {
+        let ch_width = char_width(ch);
+        if width + ch_width > max_width {
+            break;
+        }
+        output.push(ch);
+        width += ch_width;
+    }
+
+    output
+}
+
+fn display_width(text: &str) -> usize {
+    text.chars().map(char_width).sum()
+}
+
+fn char_width(ch: char) -> usize {
+    match ch {
+        '\n' | '\r' | '\t' => 1,
+        _ => {
+            let width = unsafe { wcwidth(ch as i32) };
+            if width < 0 {
+                0
+            } else {
+                width as usize
+            }
+        }
+    }
+}
+
+fn repeat_char(ch: char, count: usize) -> String {
+    std::iter::repeat_n(ch, count).collect()
+}
+
+fn join_lines(lines: Vec<String>, indent: usize) -> String {
+    let prefix = " ".repeat(indent);
+    let mut output = String::new();
+    for line in lines {
+        output.push_str(&prefix);
+        output.push_str(&line);
+        output.push('\n');
+    }
+    output
+}
