const VERSION_TEXT: &str = "csview 1.3.4\n";
const BASIC_USAGE: &str = "Usage: executable [OPTIONS] [FILE]";
const UNKNOWN_ARG_USAGE: &str = "Usage: executable <FILE|--no-headers|--number|--tsv|--delimiter <DELIMITER>|--style <STYLE>|--padding <PADDING>|--indent <INDENT>|--sniff <LIMIT>|--header-align <HEADER_ALIGN>|--body-align <BODY_ALIGN>|--disable-pager>";
const TSV_CONFLICT_USAGE: &str = "Usage: executable --tsv <FILE>";

unsafe extern "C" {
    fn wcwidth(c: i32) -> i32;
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Style {
    None,
    Ascii,
    Ascii2,
    Sharp,
    Rounded,
    Reinforced,
    Markdown,
    Grid,
}

#[derive(Clone, Copy, Debug, Eq, PartialEq)]
enum Align {
    Left,
    Center,
    Right,
}

#[derive(Debug)]
struct Cli {
    no_headers: bool,
    number: bool,
    tsv: bool,
    delimiter: char,
    style: Style,
    padding: usize,
    indent: usize,
    sniff: usize,
    header_align: Align,
    body_align: Align,
    disable_pager: bool,
    file: Option<PathBuf>,
}

impl Default for Cli {
    fn default() -> Self {
        Self {
            no_headers: false,
            number: false,
            tsv: false,
            delimiter: ',',
            style: Style::Sharp,
            padding: 1,
            indent: 0,
            sniff: 1000,
            header_align: Align::Center,
            body_align: Align::Left,
            disable_pager: false,
            file: None,
        }
    }
}

enum OutputStream {
    Stdout,
    Stderr,
}

struct CliExit {
    code: u8,
    stream: OutputStream,
    message: String,
}

impl CliExit {
    fn stdout(code: u8, message: impl Into<String>) -> Self {
        Self {
            code,
            stream: OutputStream::Stdout,
            message: message.into(),
        }
    }

    fn stderr(code: u8, message: impl Into<String>) -> Self {
        Self {
            code,
            stream: OutputStream::Stderr,
            message: message.into(),
        }
    }
}

#[derive(Clone, Copy)]
struct BoxStyle {
    top_left: char,
    top_mid: char,
    top_right: char,
    mid_left: char,
    mid_mid: char,
    mid_right: char,
    bottom_left: char,
    bottom_mid: char,
    bottom_right: char,
    horizontal: char,
    vertical: char,
    body_separators: bool,
}

struct TableData {
    header: Option<Vec<String>>,
    body: Vec<Vec<String>>,
    widths: Vec<usize>,
}

fn main() -> ExitCode {
    let args = env::args().skip(1).collect::<Vec<_>>();
    let cli = match parse_cli(&args) {
        Ok(cli) => cli,
        Err(exit) => {
            let result = match exit.stream {
                OutputStream::Stdout => io::stdout().lock().write_all(exit.message.as_bytes()),
                OutputStream::Stderr => io::stderr().lock().write_all(exit.message.as_bytes()),
            };

            if let Err(error) = result {
                if error.kind() != io::ErrorKind::BrokenPipe {
                    eprintln!("csview: {error}");
                    return ExitCode::from(1);
                }
            }

            return ExitCode::from(exit.code);
        }
    };

    let input = match read_input(cli.file.as_deref()) {
        Ok(input) => input,
        Err(error) => {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    };

    let delimiter = if cli.tsv {
        b'\t'
    } else {
        cli.delimiter as u32 as u8
    };

    let records = match parse_csv(&input, delimiter) {
        Ok(records) => records,
        Err(error) => {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    };

    let table = build_table(&cli, records);
    let rendered = render_table(&cli, &table);

    let mut stdout = io::stdout().lock();
    if let Err(error) = stdout.write_all(rendered.as_bytes()) {
        if error.kind() != io::ErrorKind::BrokenPipe {
            eprintln!("csview: {error}");
            return ExitCode::from(1);
        }
    }

    ExitCode::SUCCESS
}

fn parse_cli(args: &[String]) -> Result<Cli, CliExit> {
    if args.iter().any(|arg| arg == "-h" || arg == "--help") {
        return Err(CliExit::stdout(0, HELP_TEXT));
    }

    if args.iter().any(|arg| arg == "-V" || arg == "--version") {
        return Err(CliExit::stdout(0, VERSION_TEXT));
    }

    let mut cli = Cli::default();
    let mut delimiter_set = false;
    let mut index = 0;

    while index < args.len() {
        let arg = &args[index];

        if arg == "--" {
            index += 1;
            while index < args.len() {
                push_positional(&mut cli, &args[index])?;
                index += 1;
            }
            break;
        }

        if arg == "-" {
            push_positional(&mut cli, arg)?;
            index += 1;
            continue;
        }

        if arg == "-H" || arg == "--no-headers" {
            cli.no_headers = true;
            index += 1;
            continue;
        }

        if arg == "-n" || arg == "--number" {
            cli.number = true;
            index += 1;
            continue;
        }

        if arg == "-t" || arg == "--tsv" {
            if delimiter_set {
                return Err(tsv_conflict_message());
            }
            cli.tsv = true;
            index += 1;
            continue;
        }

        if arg == "-P" || arg == "--disable-pager" {
            cli.disable_pager = true;
            index += 1;
            continue;
        }

        if arg == "-d" || arg == "--delimiter" {
            let value = take_value(args, index + 1, "--delimiter <DELIMITER>")?;
            if cli.tsv {
                return Err(tsv_conflict_message());
            }
            cli.delimiter = parse_delimiter(&value)?;
            delimiter_set = true;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--delimiter=") {
            if cli.tsv {
                return Err(tsv_conflict_message());
            }
            cli.delimiter = parse_delimiter(value)?;
            delimiter_set = true;
            index += 1;
            continue;
        }
        if let Some(value) = short_value(arg, "-d") {
            if cli.tsv {
                return Err(tsv_conflict_message());
            }
            cli.delimiter = parse_delimiter(value)?;
            delimiter_set = true;
            index += 1;
            continue;
        }

        if arg == "-s" || arg == "--style" {
            let value = take_value(args, index + 1, "--style <STYLE>")?;
            cli.style = parse_style(&value)?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--style=") {
            cli.style = parse_style(value)?;
            index += 1;
            continue;
        }
        if let Some(value) = short_value(arg, "-s") {
            cli.style = parse_style(value)?;
            index += 1;
            continue;
        }

        if arg == "-p" || arg == "--padding" {
            let value = take_value(args, index + 1, "--padding <PADDING>")?;
            cli.padding = parse_usize(&value, "--padding <PADDING>")?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--padding=") {
            cli.padding = parse_usize(value, "--padding <PADDING>")?;
            index += 1;
            continue;
        }
        if let Some(value) = short_value(arg, "-p") {
            cli.padding = parse_usize(value, "--padding <PADDING>")?;
            index += 1;
            continue;
        }

        if arg == "-i" || arg == "--indent" {
            let value = take_value(args, index + 1, "--indent <INDENT>")?;
            cli.indent = parse_usize(&value, "--indent <INDENT>")?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--indent=") {
            cli.indent = parse_usize(value, "--indent <INDENT>")?;
            index += 1;
            continue;
        }
        if let Some(value) = short_value(arg, "-i") {
            cli.indent = parse_usize(value, "--indent <INDENT>")?;
            index += 1;
            continue;
        }

        if arg == "--sniff" {
            let value = take_value(args, index + 1, "--sniff <LIMIT>")?;
            cli.sniff = parse_usize(&value, "--sniff <LIMIT>")?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--sniff=") {
            cli.sniff = parse_usize(value, "--sniff <LIMIT>")?;
            index += 1;
            continue;
        }

        if arg == "--header-align" {
            let value = take_value(args, index + 1, "--header-align <HEADER_ALIGN>")?;
            cli.header_align = parse_align(&value, "--header-align <HEADER_ALIGN>")?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--header-align=") {
            cli.header_align = parse_align(value, "--header-align <HEADER_ALIGN>")?;
            index += 1;
            continue;
        }

        if arg == "--body-align" {
            let value = take_value(args, index + 1, "--body-align <BODY_ALIGN>")?;
            cli.body_align = parse_align(&value, "--body-align <BODY_ALIGN>")?;
            index += 2;
            continue;
        }
        if let Some(value) = arg.strip_prefix("--body-align=") {
            cli.body_align = parse_align(value, "--body-align <BODY_ALIGN>")?;
            index += 1;
            continue;
        }

        if arg.starts_with('-') {
            return Err(unexpected_argument(arg, suggestion_for(arg), UNKNOWN_ARG_USAGE));
        }

        push_positional(&mut cli, arg)?;
        index += 1;
    }

    Ok(cli)
}

fn push_positional(cli: &mut Cli, value: &str) -> Result<(), CliExit> {
    if cli.file.is_some() {
        return Err(unexpected_argument(value, suggestion_for(value), BASIC_USAGE));
    }

    cli.file = Some(PathBuf::from(value));
    Ok(())
}

fn take_value(args: &[String], index: usize, option: &str) -> Result<String, CliExit> {
    match args.get(index) {
        None => Err(missing_value(option)),
        Some(value) if value.starts_with('-') && value != "-" => {
            Err(unexpected_argument(value, suggestion_for(value), BASIC_USAGE))
        }
        Some(value) => Ok(value.clone()),
    }
}

fn short_value<'a>(arg: &'a str, flag: &str) -> Option<&'a str> {
    let rest = arg.strip_prefix(flag)?;
    if rest.is_empty() {
        None
    } else {
        Some(rest.strip_prefix('=').unwrap_or(rest))
    }
}

fn parse_delimiter(value: &str) -> Result<char, CliExit> {
    let mut chars = value.chars();
    let Some(ch) = chars.next() else {
        return Err(invalid_value(
            value,
            "--delimiter <DELIMITER>",
            "cannot parse char from empty string",
        ));
    };

    if chars.next().is_some() {
        return Err(invalid_value(
            value,
            "--delimiter <DELIMITER>",
            "too many characters in string",
        ));
    }

    Ok(ch)
}

fn parse_style(value: &str) -> Result<Style, CliExit> {
    match value {
        "none" => Ok(Style::None),
        "ascii" => Ok(Style::Ascii),
        "ascii2" => Ok(Style::Ascii2),
        "sharp" => Ok(Style::Sharp),
        "rounded" => Ok(Style::Rounded),
        "reinforced" => Ok(Style::Reinforced),
        "markdown" => Ok(Style::Markdown),
        "grid" => Ok(Style::Grid),
        _ => Err(CliExit::stderr(
            2,
            format!(
                "error: invalid value '{}' for '--style <STYLE>'\n  [possible values: none, ascii, ascii2, sharp, rounded, reinforced, markdown, grid]\n\nFor more information, try '--help'.\n",
                value
            ),
        )),
    }
}

fn parse_align(value: &str, option: &str) -> Result<Align, CliExit> {
    match value {
        "left" => Ok(Align::Left),
        "center" => Ok(Align::Center),
        "right" => Ok(Align::Right),
        _ => Err(CliExit::stderr(
            2,
            format!(
                "error: invalid value '{}' for '{}'\n  [possible values: left, center, right]\n\nFor more information, try '--help'.\n",
                value, option
            ),
        )),
    }
}

fn parse_usize(value: &str, option: &str) -> Result<usize, CliExit> {
    value
        .parse::<usize>()
        .map_err(|error| invalid_value(value, option, &error.to_string()))
}

fn invalid_value(value: &str, option: &str, detail: &str) -> CliExit {
    CliExit::stderr(
        2,
        format!(
            "error: invalid value '{}' for '{}': {}\n\nFor more information, try '--help'.\n",
            value, option, detail
        ),
    )
}

fn missing_value(option: &str) -> CliExit {
    CliExit::stderr(
        2,
        format!(
            "error: a value is required for '{}' but none was supplied\n\nFor more information, try '--help'.\n",
            option
        ),
    )
}

fn unexpected_argument(argument: &str, suggestion: Option<&str>, usage: &str) -> CliExit {
    let tip = suggestion
        .map(|flag| format!("\n  tip: a similar argument exists: '{}'\n", flag))
        .unwrap_or_default();

    CliExit::stderr(
        2,
        format!(
            "error: unexpected argument '{}' found\n{}\n{}\n\nFor more information, try '--help'.\n",
            argument, tip, usage
        ),
    )
}

fn tsv_conflict_message() -> CliExit {
    CliExit::stderr(
        2,
        format!(
            "error: the argument '--tsv' cannot be used with '--delimiter <DELIMITER>'\n\n{}\n\nFor more information, try '--help'.\n",
            TSV_CONFLICT_USAGE
        ),
    )
}

fn suggestion_for(argument: &str) -> Option<&'static str> {
    if argument == "--badflag" {
        Some("--disable-pager")
    } else {
        None
    }
}

fn read_input(path: Option<&Path>) -> io::Result<Vec<u8>> {
    let mut data = Vec::new();
    match path {
        Some(path) => File::open(path)?.read_to_end(&mut data)?,
        None => io::stdin().lock().read_to_end(&mut data)?,
    };
    Ok(data)
}

fn parse_csv(data: &[u8], delimiter: u8) -> Result<Vec<Vec<String>>, String> {
    let mut records = Vec::new();
    let mut expected_fields = None;
    let mut record_fields: Vec<Vec<u8>> = Vec::new();
    let mut field = Vec::new();
    let mut in_quotes = false;
    let mut just_closed_quote = false;
    let mut record_has_content = false;
    let mut line = 1usize;
    let mut record_start_line = 1usize;
    let mut record_start_byte = 0usize;
    let mut index = 0usize;

    while index < data.len() {
        let byte = data[index];

        if in_quotes {
            if byte == b'"' {
                if data.get(index + 1) == Some(&b'"') {
                    field.push(b'"');
                    record_has_content = true;
                    index += 2;
                    continue;
                }

                in_quotes = false;
                just_closed_quote = true;
                index += 1;
                continue;
            }

            if byte == b'\r' && data.get(index + 1) == Some(&b'\n') {
                field.push(b'\r');
                field.push(b'\n');
                record_has_content = true;
                line += 1;
                index += 2;
                continue;
            }

            field.push(byte);
            record_has_content = true;
            if byte == b'\n' || byte == b'\r' {
                line += 1;
            }
            index += 1;
            continue;
        }

        if just_closed_quote {
            if byte == delimiter {
                record_fields.push(std::mem::take(&mut field));
                just_closed_quote = false;
                record_has_content = true;
                index += 1;
                continue;
            }

            if byte == b'\n' {
                record_fields.push(std::mem::take(&mut field));
                just_closed_quote = false;
                finalize_record(
                    &mut records,
                    &mut expected_fields,
                    &mut record_fields,
                    record_has_content,
                    record_start_line,
                    record_start_byte,
                )?;
                record_has_content = false;
                line += 1;
                index += 1;
                record_start_line = line;
                record_start_byte = index;
                continue;
            }

            if byte == b'\r' {
                record_fields.push(std::mem::take(&mut field));
                just_closed_quote = false;
                finalize_record(
                    &mut records,
                    &mut expected_fields,
                    &mut record_fields,
                    record_has_content,
                    record_start_line,
                    record_start_byte,
                )?;
                record_has_content = false;
                line += 1;
                if data.get(index + 1) == Some(&b'\n') {
                    index += 2;
                } else {
                    index += 1;
                }
                record_start_line = line;
                record_start_byte = index;
                continue;
            }

            return Err(invalid_csv_syntax(records.len(), record_start_line, record_start_byte));
        }

        if byte == delimiter {
            record_fields.push(std::mem::take(&mut field));
            record_has_content = true;
            index += 1;
            continue;
        }

        if byte == b'"' {
            if field.is_empty() {
                in_quotes = true;
                record_has_content = true;
                index += 1;
                continue;
            }

            return Err(invalid_csv_syntax(records.len(), record_start_line, record_start_byte));
        }

        if byte == b'\n' {
            record_fields.push(std::mem::take(&mut field));
            finalize_record(
                &mut records,
                &mut expected_fields,
                &mut record_fields,
                record_has_content,
                record_start_line,
                record_start_byte,
            )?;
            record_has_content = false;
            line += 1;
            index += 1;
            record_start_line = line;
            record_start_byte = index;
            continue;
        }

        if byte == b'\r' {
            record_fields.push(std::mem::take(&mut field));
            finalize_record(
                &mut records,
                &mut expected_fields,
                &mut record_fields,
                record_has_content,
                record_start_line,
                record_start_byte,
            )?;
            record_has_content = false;
            line += 1;
            if data.get(index + 1) == Some(&b'\n') {
                index += 2;
            } else {
                index += 1;
            }
            record_start_line = line;
            record_start_byte = index;
            continue;
        }

        field.push(byte);
        record_has_content = true;
        index += 1;
    }

    if in_quotes {
        return Err(invalid_csv_syntax(records.len(), record_start_line, record_start_byte));
    }

    if just_closed_quote || !field.is_empty() || !record_fields.is_empty() || record_has_content {
        record_fields.push(field);
        finalize_record(
            &mut records,
            &mut expected_fields,
            &mut record_fields,
            record_has_content,
            record_start_line,
            record_start_byte,
        )?;
    }

    Ok(records)
}

fn finalize_record(
    records: &mut Vec<Vec<String>>,
    expected_fields: &mut Option<usize>,
    record_fields: &mut Vec<Vec<u8>>,
    record_has_content: bool,
    record_start_line: usize,
    record_start_byte: usize,
) -> Result<(), String> {
    if !record_has_content && record_fields.len() == 1 && record_fields[0].is_empty() {
        record_fields.clear();
        return Ok(());
    }

    let record_index = records.len();
    let mut record = Vec::with_capacity(record_fields.len());
    for field in record_fields.drain(..) {
        let text = String::from_utf8(field)
            .map_err(|_| invalid_csv_syntax(record_index, record_start_line, record_start_byte))?;
        record.push(text);
    }

    if let Some(previous_fields) = expected_fields {
        if record.len() != *previous_fields {
            return Err(format!(
                "CSV error: record {} (line: {}, byte: {}): found record with {} fields, but the previous record has {} fields",
                record_index,
                record_start_line,
                record_start_byte,
                record.len(),
                previous_fields
            ));
        }
    } else {
        *expected_fields = Some(record.len());
    }

    records.push(record);
    Ok(())
}

fn invalid_csv_syntax(record_index: usize, line: usize, byte: usize) -> String {
    format!(
        "CSV error: record {} (line: {}, byte: {}): found invalid CSV syntax",
        record_index, line, byte
    )
}

fn build_table(cli: &Cli, records: Vec<Vec<String>>) -> TableData {
    let (mut header, mut body) = if cli.no_headers {
        (None, records)
    } else if records.is_empty() {
        (Some(Vec::new()), Vec::new())
    } else {
        let mut records = records;
        let header = records.remove(0);
        (Some(header), records)
    };

    if cli.number {
        if let Some(header) = header.as_mut() {
            header.insert(0, "#".to_owned());
        }

        for (index, row) in body.iter_mut().enumerate() {
            row.insert(0, (index + 1).to_string());
        }
    }

    let column_count = if let Some(header) = &header {
        header.len()
    } else if let Some(first_row) = body.first() {
        first_row.len()
    } else if cli.number {
        1
    } else {
        0
    };

    let mut widths = vec![0; column_count];
    if let Some(header) = &header {
        update_widths(&mut widths, header);
    }

    let sniff_rows = if cli.sniff == 0 {
        body.len()
    } else {
        body.len().min(cli.sniff)
    };

    for row in body.iter().take(sniff_rows) {
        update_widths(&mut widths, row);
    }

    if cli.number && header.is_none() && body.is_empty() && !widths.is_empty() {
        widths[0] = 1;
    }

    TableData {
        header,
        body,
        widths,
    }
}

fn update_widths(widths: &mut [usize], row: &[String]) {
    for (width, cell) in widths.iter_mut().zip(row) {
        *width = (*width).max(display_width(cell));
    }
}

fn render_table(cli: &Cli, table: &TableData) -> String {
    let _ = cli.disable_pager;

    match cli.style {
        Style::None => render_none(cli, table),
        Style::Ascii2 => render_ascii2(cli, table),
        Style::Markdown => render_markdown(cli, table),
        Style::Ascii => render_box(
            cli,
            table,
            BoxStyle {
                top_left: '+',
                top_mid: '+',
                top_right: '+',
                mid_left: '+',
                mid_mid: '+',
                mid_right: '+',
                bottom_left: '+',
                bottom_mid: '+',
                bottom_right: '+',
                horizontal: '-',
                vertical: '|',
                body_separators: false,
            },
        ),
        Style::Sharp => render_box(
            cli,
            table,
            BoxStyle {
                top_left: '┌',
                top_mid: '┬',
                top_right: '┐',
                mid_left: '├',
                mid_mid: '┼',
                mid_right: '┤',
                bottom_left: '└',
                bottom_mid: '┴',
                bottom_right: '┘',
                horizontal: '─',
                vertical: '│',
                body_separators: false,
            },
        ),
        Style::Rounded => render_box(
            cli,
            table,
            BoxStyle {
                top_left: '╭',
                top_mid: '┬',
                top_right: '╮',
                mid_left: '├',
                mid_mid: '┼',
                mid_right: '┤',
                bottom_left: '╰',
                bottom_mid: '┴',
                bottom_right: '╯',
                horizontal: '─',
                vertical: '│',
                body_separators: false,
            },
        ),
        Style::Reinforced => render_box(
            cli,
            table,
            BoxStyle {
                top_left: '┏',
                top_mid: '┬',
                top_right: '┓',
                mid_left: '├',
                mid_mid: '┼',
                mid_right: '┤',
                bottom_left: '┗',
                bottom_mid: '┴',
                bottom_right: '┛',
                horizontal: '─',
                vertical: '│',
                body_separators: false,
            },
        ),
        Style::Grid => render_box(
            cli,
            table,
            BoxStyle {
                top_left: '┌',
                top_mid: '┬',
                top_right: '┐',
                mid_left: '├',
                mid_mid: '┼',
                mid_right: '┤',
                bottom_left: '└',
                bottom_mid: '┴',
                bottom_right: '┘',
                horizontal: '─',
                vertical: '│',
                body_separators: true,
            },
        ),
    }
}

fn render_box(cli: &Cli, table: &TableData, style: BoxStyle) -> String {
    let mut lines = Vec::new();
    lines.push(render_border(
        &table.widths,
        cli.padding,
        style.top_left,
        style.top_mid,
        style.top_right,
        style.horizontal,
    ));

    if let Some(header) = &table.header {
        lines.push(render_box_row(
            header,
            &table.widths,
            cli.padding,
            cli.header_align,
            style.vertical,
        ));

        if !table.body.is_empty() {
            lines.push(render_border(
                &table.widths,
                cli.padding,
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.horizontal,
            ));
        }
    }

    for (index, row) in table.body.iter().enumerate() {
        lines.push(render_box_row(
            row,
            &table.widths,
            cli.padding,
            cli.body_align,
            style.vertical,
        ));

        if style.body_separators && index + 1 < table.body.len() {
            lines.push(render_border(
                &table.widths,
                cli.padding,
                style.mid_left,
                style.mid_mid,
                style.mid_right,
                style.horizontal,
            ));
        }
    }

    lines.push(render_border(
        &table.widths,
        cli.padding,
        style.bottom_left,
        style.bottom_mid,
        style.bottom_right,
        style.horizontal,
    ));

    join_lines(lines, cli.indent)
}

fn render_none(cli: &Cli, table: &TableData) -> String {
    let mut lines = Vec::new();

    if let Some(header) = &table.header {
        lines.push(render_flat_row(
            header,
            &table.widths,
            cli.padding,
            cli.header_align,
            "",
            "",
            "",
        ));
    }

    for row in &table.body {
        lines.push(render_flat_row(
            row,
            &table.widths,
            cli.padding,
            cli.body_align,
            "",
            "",
            "",
        ));
    }

    if lines.is_empty() {
        String::new()
    } else {
        join_lines(lines, cli.indent)
    }
}

fn render_ascii2(cli: &Cli, table: &TableData) -> String {
    let mut lines = Vec::new();

    if let Some(header) = &table.header {
        lines.push(render_flat_row(
            header,
            &table.widths,
            cli.padding,
            cli.header_align,
            "",
            "|",
            "",
        ));

        if !table.body.is_empty() {
            lines.push(render_separator_row(
                &table.widths,
                cli.padding,
                "",
                "+",
                "",
                '-',
                Some(' '),
            ));
        }
    }

    for row in &table.body {
        lines.push(render_flat_row(
            row,
            &table.widths,
            cli.padding,
            cli.body_align,
            "",
            "|",
            "",
        ));
    }

    if lines.is_empty() {
        String::new()
    } else {
        join_lines(lines, cli.indent)
    }
}

fn render_markdown(cli: &Cli, table: &TableData) -> String {
    let mut lines = Vec::new();

    if let Some(header) = &table.header {
        lines.push(render_flat_row(
            header,
            &table.widths,
            cli.padding,
            cli.header_align,
            "|",
            "|",
            "|",
        ));

        if !table.body.is_empty() {
            lines.push(render_separator_row(
                &table.widths,
                cli.padding,
                "|",
                "|",
                "|",
                '-',
                None,
            ));
        }
    }

    for row in &table.body {
        lines.push(render_flat_row(
            row,
            &table.widths,
            cli.padding,
            cli.body_align,
            "|",
            "|",
            "|",
        ));
    }

    if lines.is_empty() {
        String::new()
    } else {
        join_lines(lines, cli.indent)
    }
}

fn render_border(
    widths: &[usize],
    padding: usize,
    left: char,
    mid: char,
    right: char,
    horizontal: char,
) -> String {
    if widths.is_empty() {
        return format!("{left}{right}");
    }

    let segments = widths
        .iter()
        .map(|width| repeat_char(horizontal, width + (padding * 2)))
        .collect::<Vec<_>>();

    format!("{left}{}{right}", segments.join(&mid.to_string()))
}

fn render_box_row(
    row: &[String],
    widths: &[usize],
    padding: usize,
    align: Align,
    vertical: char,
) -> String {
    if widths.is_empty() {
        return format!("{vertical}{vertical}");
    }

    let cells = widths
        .iter()
        .zip(row.iter())
        .map(|(width, cell)| render_cell(cell, *width, padding, align))
        .collect::<Vec<_>>();

    format!("{vertical}{}{vertical}", cells.join(&vertical.to_string()))
}

fn render_flat_row(
    row: &[String],
    widths: &[usize],
    padding: usize,
    align: Align,
    left_edge: &str,
    separator: &str,
    right_edge: &str,
) -> String {
    if widths.is_empty() {
        return format!("{left_edge}{right_edge}");
    }

    let cells = widths
        .iter()
        .zip(row.iter())
        .map(|(width, cell)| render_cell(cell, *width, padding, align))
        .collect::<Vec<_>>();

    format!("{left_edge}{}{right_edge}", cells.join(separator))
}

fn render_separator_row(
    widths: &[usize],
    padding: usize,
    left_edge: &str,
    separator: &str,
    right_edge: &str,
    fill: char,
    outer_padding: Option<char>,
) -> String {
    if widths.is_empty() {
        return match outer_padding {
            Some(ch) => {
                let mut line = String::new();
                line.push(ch);
                line.push_str(left_edge);
                line.push_str(right_edge);
                line.push(ch);
                line
            }
            None => format!("{left_edge}{right_edge}"),
        };
    }

    let cells = widths
        .iter()
        .map(|width| repeat_char(fill, width + (padding * 2)))
        .collect::<Vec<_>>();

    let mut line = format!("{left_edge}{}{right_edge}", cells.join(separator));
    if let Some(ch) = outer_padding {
        line.insert(0, ch);
        line.push(ch);
    }

    line
}

fn render_cell(text: &str, width: usize, padding: usize, align: Align) -> String {
    let text = truncate_to_width(text, width);
    let text_width = display_width(&text);
    let slack = width.saturating_sub(text_width);
    let (left_extra, right_extra) = match align {
        Align::Left => (0, slack),
        Align::Center => (slack / 2, slack - (slack / 2)),
        Align::Right => (slack, 0),
    };

    format!(
        "{}{}{}",
        " ".repeat(padding + left_extra),
        text,
        " ".repeat(padding + right_extra)
    )
}

fn truncate_to_width(text: &str, max_width: usize) -> String {
    if display_width(text) <= max_width {
        return text.to_owned();
    }

    let mut output = String::new();
    let mut width = 0;

    // Later rows are clipped to the sniffed width with no ellipsis.
    for ch in text.chars() {
        let ch_width = char_width(ch);
        if width + ch_width > max_width {
            break;
        }
        output.push(ch);
        width += ch_width;
    }

    output
}

fn display_width(text: &str) -> usize {
    text.chars().map(char_width).sum()
}

fn char_width(ch: char) -> usize {
    match ch {
        '\n' | '\r' | '\t' => 1,
        _ => {
            let width = unsafe { wcwidth(ch as i32) };
            if width < 0 {
                0
            } else {
                width as usize
            }
        }
    }
}

fn repeat_char(ch: char, count: usize) -> String {
    std::iter::repeat_n(ch, count).collect()
}

fn join_lines(lines: Vec<String>, indent: usize) -> String {
    let prefix = " ".repeat(indent);
    let mut output = String::new();
    for line in lines {
        output.push_str(&prefix);
        output.push_str(&line);
        output.push('\n');
    }
    output
}

